\title{Fourier Analysis on Finite Cyclic Groups: Convolution, Parseval, and the Donoho--Stark Uncertainty Principle}
\author{Aristotle}
\date{2026-07-01}

\begin{document}
\begin{abstract}
We develop the discrete Fourier transform on the finite cyclic group $\Z/N\Z$ from the viewpoint of the representation theory of abelian groups, and prove its three fundamental structural theorems in fully explicit, self-contained form: the \emph{convolution theorem} $\widehat{f\star g}=\hat f\cdot\hat g$; the \emph{Parseval/Plancherel identity} $\sum_k|\hat f(k)|^2 = N\sum_j|f(j)|^2$; and the \emph{Donoho--Stark uncertainty principle} $|\supp f|\cdot|\supp\hat f|\ge N$ for every nonzero $f$. A central contribution is a clean stratification of the hypotheses: the convolution theorem requires only that characters are multiplicative; Parseval additionally requires character orthogonality; the uncertainty principle requires neither, resting solely on the facts that characters have modulus one and that the transform is invertible. We isolate two Hölder-type mixed bounds as the analytic engine of the uncertainty inequality, show the extremal signals are the subgroup indicators, and close with three conjectures.
\end{abstract}
\maketitle

\section{Introduction}
Fourier analysis exchanges two descriptions of a signal: a spatial description recording its value at each point, and a spectral description recording its content in each pure frequency. On a finite cyclic group these are related by a linear isomorphism, the discrete Fourier transform (DFT), elementary enough to write down completely yet rich enough to exhibit every phenomenon of harmonic analysis in exact, finite form.

We present the three pillars of this theory, adopting the perspective that the DFT is the decomposition of a function into the additive characters of the group, and we make explicit exactly which property of characters powers each result. The payoff is conceptual: the celebrated support uncertainty principle of Donoho and Stark is, in its hypotheses, weaker than the convolution and Parseval theorems, needing only that characters are unimodular and that inversion holds.

\section{Setup and definitions}
Fix an integer $N\ge 1$ and work over $G=\Z/N\Z=\{0,1,\dots,N-1\}$ under addition modulo $N$. A \emph{signal} is a function $f\colon\Z/N\Z\to\C$; the signals form an $N$-dimensional complex vector space.

\subsection{Characters}
An \emph{additive character} is a function $\chi$ with $\chi(a+b)=\chi(a)\chi(b)$. We fix the \emph{standard character} $\chi(m)=e^{2\pi i m/N}$, which is primitive (nontrivial on every nonzero element). We use three properties:
\begin{itemize}
\item[(C1)] \textbf{Unimodularity:} $|\chi(m)|=1$ for all $m$.
\item[(C2)] \textbf{Multiplicativity:} $\chi(a+b)=\chi(a)\chi(b)$; in particular $\chi(0)=1$, $\chi(-m)=\overline{\chi(m)}$.
\item[(C3)] \textbf{Orthogonality:} $\sum_{k=0}^{N-1}\chi(mk)=N$ if $m=0$ and $0$ otherwise.
\end{itemize}
Property (C3) follows from primitivity via the finite geometric series.

\subsection{The discrete Fourier transform}
The \emph{discrete Fourier transform} of $f$ is
\[
\hat f(k)=\F f(k)=\sum_{j=0}^{N-1} f(j)\,\overline{\chi(jk)}=\sum_{j=0}^{N-1} f(j)\,\chi(-jk),
\]
a linear isomorphism with inverse (Fourier inversion)
\[
f(j)=\frac{1}{N}\sum_{k=0}^{N-1}\hat f(k)\,\chi(kj),
\]
itself a consequence of orthogonality (C3).

\subsection{Support and norms}
The \emph{support} is $\supp f=\{\,j:f(j)\ne 0\,\}$ with cardinality $|\supp f|$. We use $\norm{f}_1=\sum_j|f(j)|$, $\norm{f}_2=(\sum_j|f(j)|^2)^{1/2}$, and the sup-norm $\norm{f}_\infty=\max_j|f(j)|$. Since $G$ is finite and nonempty, the maximum is attained and $\norm{f}_\infty>0$ iff $f\ne 0$.

\section{Elementary norm estimates}
\begin{lemma}[Sup-norm dominates values]\label{lem:sup}
For every $f$ and every $j$, $|f(j)|\le\norm{f}_\infty$; moreover $\norm{f}_\infty\ge 0$, with $\norm{f}_\infty>0$ iff $f\ne 0$.
\end{lemma}
\begin{proof}
$|f(j)|$ is one of the finitely many quantities in the maximum. Nonnegativity is clear; positivity is equivalent to some value being nonzero.
\end{proof}

\begin{lemma}[$L^1$ bound on Fourier coefficients]\label{lem:l1}
For every $f$ and $k$, $|\hat f(k)|\le\norm{f}_1=\sum_j|f(j)|$.
\end{lemma}
\begin{proof}
By the triangle inequality and (C1), $|\hat f(k)|\le\sum_j|f(j)|\,|\chi(-jk)|=\sum_j|f(j)|$.
\end{proof}

\begin{lemma}[Dual $L^1$ bound from inversion]\label{lem:dual}
For every $f$ and $j$, $|f(j)|\le\frac{1}{N}\sum_k|\hat f(k)|=\frac{1}{N}\norm{\hat f}_1$.
\end{lemma}
\begin{proof}
Apply inversion, take absolute values, and use the triangle inequality with $|\chi(kj)|=1$.
\end{proof}

\begin{lemma}[$L^1\le$ support $\times$ sup-norm]\label{lem:card}
For every $f$, $\norm{f}_1\le|\supp f|\cdot\norm{f}_\infty$.
\end{lemma}
\begin{proof}
Only support points contribute; bounding each of the $|\supp f|$ terms by $\norm{f}_\infty$ gives the claim.
\end{proof}

\section{The convolution theorem}
\begin{definition}[Cyclic convolution]
$(f\star g)(x)=\sum_{y=0}^{N-1} f(y)\,g(x-y)$, with arithmetic in $\Z/N\Z$.
\end{definition}

\begin{theorem}[Convolution theorem]\label{thm:conv}
For all $f,g$ and every $k$, $\widehat{f\star g}(k)=\hat f(k)\cdot\hat g(k)$.
\end{theorem}
\begin{proof}
Interchanging finite sums,
\[
\widehat{f\star g}(k)=\sum_y f(y)\sum_x \chi(-xk)\,g(x-y).
\]
Substituting $z=x-y$ (a bijection of $\Z/N\Z$) and using (C2), $\chi(-(z+y)k)=\chi(-yk)\chi(-zk)$, so the inner sum equals $\chi(-yk)\hat g(k)$. Hence $\widehat{f\star g}(k)=\hat f(k)\hat g(k)$. Only (C2) and a change of variables were used.
\end{proof}

\section{Character orthogonality and Parseval}
\begin{lemma}[Character orthogonality]\label{lem:orth}
For every $m$, $\sum_{k=0}^{N-1}\chi(mk)=N$ if $m=0$ and $0$ otherwise.
\end{lemma}
\begin{proof}
If $m=0$ every term is $1$. If $m\ne 0$, $\chi(m)\ne1$ is a root of unity and the geometric series over a full period vanishes.
\end{proof}

\begin{theorem}[Parseval/Plancherel]\label{thm:parseval}
For every $f$, $\sum_{k=0}^{N-1}|\hat f(k)|^2=N\sum_{j=0}^{N-1}|f(j)|^2$.
\end{theorem}
\begin{proof}
Expanding $|\hat f(k)|^2=\hat f(k)\overline{\hat f(k)}$ and reordering sums,
\[
\sum_k|\hat f(k)|^2=\sum_{j}\sum_{l} f(j)\overline{f(l)}\sum_k\chi((l-j)k).
\]
By Lemma~\ref{lem:orth} the inner sum is $N$ if $l=j$ and $0$ otherwise, collapsing to $N\sum_j|f(j)|^2$.
\end{proof}
The constant $N$ is forced: for $f=\delta_0$, $\hat f\equiv1$ gives $\sum_k|\hat f(k)|^2=N$ while $\sum_j|f(j)|^2=1$. Parseval used exactly one ingredient beyond Theorem~\ref{thm:conv}: orthogonality (C3).

\section{The uncertainty principle}
\begin{proposition}[First mixed bound]\label{prop:mix1}
For every $f$, $\norm{\hat f}_\infty\le|\supp f|\cdot\norm{f}_\infty$.
\end{proposition}
\begin{proof}
By Lemmas~\ref{lem:l1} and~\ref{lem:card}, $|\hat f(k)|\le\norm{f}_1\le|\supp f|\cdot\norm{f}_\infty$; take the max over $k$.
\end{proof}

\begin{proposition}[Second mixed bound]\label{prop:mix2}
For every $f$, $\norm{f}_\infty\le\frac{1}{N}|\supp\hat f|\cdot\norm{\hat f}_\infty$.
\end{proposition}
\begin{proof}
By Lemmas~\ref{lem:dual} and~\ref{lem:card} (applied to $\hat f$), $|f(j)|\le\frac1N\norm{\hat f}_1\le\frac1N|\supp\hat f|\cdot\norm{\hat f}_\infty$; take the max over $j$.
\end{proof}

\begin{theorem}[Donoho--Stark uncertainty principle]\label{thm:unc}
For every nonzero $f\colon\Z/N\Z\to\C$, $|\supp f|\cdot|\supp\hat f|\ge N$.
\end{theorem}
\begin{proof}
Chaining Propositions~\ref{prop:mix1} and~\ref{prop:mix2},
\[
\norm{\hat f}_\infty\le|\supp f|\cdot\norm{f}_\infty\le|\supp f|\cdot\frac1N|\supp\hat f|\cdot\norm{\hat f}_\infty.
\]
Since $f\ne 0$, $\hat f\ne 0$ (invertibility), so $\norm{\hat f}_\infty>0$ by Lemma~\ref{lem:sup}. Dividing gives $1\le\frac1N|\supp f|\cdot|\supp\hat f|$.
\end{proof}

\begin{corollary}
No nonzero signal has both $|\supp f|<\sqrt N$ and $|\supp\hat f|<\sqrt N$; a unit impulse has full-support transform.
\end{corollary}

\section{Extremal signals}
\begin{definition}
For a subgroup $H\le\Z/N\Z$, $\ind_H$ is its indicator. Every subgroup is $H_d=\{0,d,2d,\dots\}$ of order $N/d$ for a divisor $d\mid N$.
\end{definition}

\begin{proposition}\label{prop:extremal}
If $H\le\Z/N\Z$, then $\widehat{\ind_H}=|H|\cdot\ind_{H^\perp}$ where $H^\perp=\{k:\chi(hk)=1\ \forall h\in H\}$ has order $N/|H|$; hence
$|\supp\ind_H|\cdot|\supp\widehat{\ind_H}|=|H|\cdot\frac{N}{|H|}=N$, meeting Theorem~\ref{thm:unc} with equality.
\end{proposition}
\begin{proof}
For $k\in H^\perp$ each term of $\sum_{h\in H}\chi(-hk)$ is $1$, giving $|H|$; for $k\notin H^\perp$ the sum is over a nontrivial character of $H$ and vanishes. Duality gives $|H^\perp|=N/|H|$.
\end{proof}
Translation and modulation preserve extremality, producing equality at every divisor pair $(d,N/d)$.

\section{Algorithms}
\textbf{Direct DFT:} $O(N^2)$ by definition; the correctness reference.
\textbf{Fast convolution:} transform, multiply pointwise, inverse-transform; $O(N\log N)$ via Theorem~\ref{thm:conv}, versus $O(N^2)$ directly.
\textbf{Support-product check:} count nonzeros of $f$ and $\hat f$ and verify $|\supp f|\cdot|\supp\hat f|\ge N$, with equality on subgroup indicators.

\section{Discussion and future directions}
The organizing insight is a stratification of hypotheses: the convolution theorem needs only (C2); Parseval additionally needs (C3); the uncertainty principle needs neither, only (C1) and invertibility. Since (C1)--(C3) and inversion hold for any finite abelian group via Pontryagin duality, the development transfers verbatim.

\begin{conjecture}[Prime-order additive strengthening]
For prime $p$ and nonzero $f$ on $\Z/p\Z$, $|\supp f|+|\supp\hat f|\ge p+1$. The mechanism is a Chebot\"arev-type nonvanishing of Vandermonde minors at roots of unity.
\end{conjecture}

\begin{conjecture}[Equality classification]
Equality $|\supp f|\cdot|\supp\hat f|=N$ holds iff $f$ is a scalar translate-modulation of a subgroup indicator; the achievable sizes are exactly $\{(d,N/d):d\mid N\}$.
\end{conjecture}

\begin{conjecture}[General finite abelian groups]
For every finite abelian $G$ and nonzero $f\colon G\to\C$, $|\supp f|\cdot|\supp\hat f|\ge|G|$, with equality exactly for translated, modulated subgroup indicators under the Pontryagin dual transform.
\end{conjecture}

\section{Conclusion}
On $\Z/N\Z$ the discrete Fourier transform is at once an isomorphism, an algebra homomorphism from convolution to multiplication, an isometry up to scale, and a rigid constraint on joint support. Tracking which property of characters powers each theorem reveals the Donoho--Stark principle as emerging from the humblest hypotheses of all, in a finite setting where every statement is exact and every constant forced.

\end{document}

