"""Uncertainty principle demo: |supp f|.|supp f_hat| >= N, equality on subgroups."""
from __future__ import annotations
import cmath, math
from typing import List

def dft(f: List[complex]) -> List[complex]:
    n = len(f)
    return [sum(f[j]*cmath.exp(-2j*math.pi*j*k/n) for j in range(n)) for k in range(n)]

def support_size(f: List[complex], tol: float = 1e-9) -> int:
    return sum(1 for z in f if abs(z) > tol)

if __name__ == "__main__":
    n = 12
    for d in (1, 2, 3, 4, 6, 12):
        f = [complex(1) if j % d == 0 else complex(0) for j in range(n)]
        s, sh = support_size(f), support_size(dft(f))
        print(f"d={d}: {s}*{sh}={s*sh} (N={n}, equality={s*sh==n})")

