function DFT(f[0..N-1]):
  for k in 0..N-1:
    fhat[k] = 0
    for j in 0..N-1:
      fhat[k] += f[j] * exp(-2*pi*i*j*k/N)
  return fhat

function IDFT(fhat[0..N-1]):
  for j in 0..N-1:
    f[j] = 0
    for k in 0..N-1:
      f[j] += fhat[k] * exp(+2*pi*i*j*k/N)
    f[j] /= N
  return f

function FastConvolution(f, g):
  F = DFT(f)
  G = DFT(g)
  for k in 0..N-1: P[k] = F[k] * G[k]
  return IDFT(P)

function UncertaintyCheck(f, tol):
  fhat = DFT(f)
  s_time = count(|f[j]| > tol)
  s_freq = count(|fhat[k]| > tol)
  return (s_time, s_freq, s_time*s_freq, s_time*s_freq >= N)

